#include "stdafx.h"
#include "ItemManager.h"
#include "inventory.hpp"
#include <stdexcept>
#include <cstring>
#include <algorithm>
namespace mu::client {
static_assert(MAX_ITEM_INFO==12&&sizeof(PMSG_ITEM_LIST)==13&&INVENTORY_SIZE==236,"EX603 item wire layout changed");
namespace {void need(bool ok,const char* error){if(!ok)throw std::runtime_error(error);}Item read(const std::vector<std::uint8_t>& b,unsigned offset){need(offset+12<=b.size(),"Truncated item bytes");std::array<std::uint8_t,12> raw;std::copy_n(b.begin()+offset,12,raw.begin());return decode_item(raw);}}
Item decode_item(const std::array<std::uint8_t,12>& b){Item item;item.wire=b;item.index=b[0]|((b[3]&128)<<1)|((b[5]&240)<<5);need(item.index<8191,"Empty item marker in occupied slot");item.level=(b[1]>>3)&15;item.skill=b[1]&128;item.luck=b[1]&4;item.option=(b[1]&3)+((b[3]&64)>>4);item.durability=b[2];item.excellent=b[3]&63;item.setOption=b[4];item.extended=b[5]&8;return item;}
ItemSlots decode_item_list(const std::vector<std::uint8_t>& b,unsigned header,unsigned limit){need(header>0&&b.size()>=header,"Truncated item list");unsigned count=b[header-1];need(b.size()==header+count*sizeof(PMSG_ITEM_LIST),"Item list count/size mismatch");ItemSlots items;for(unsigned i=0;i<count;i++){unsigned offset=header+i*sizeof(PMSG_ITEM_LIST),slot=b[offset];need(slot<limit,"Item slot outside container");need(items.emplace(slot,read(b,offset+1)).second,"Duplicate item slot");}return items;}
bool apply_inventory_packet(InventorySnapshot& state,const std::vector<std::uint8_t>& b){
 need(b.size()>=3,"Truncated inventory frame");unsigned offset=b[0]==0xC2?3:2;need(b.size()>offset,"Truncated inventory head");
 if(b[offset]==0xF3&&b.size()>offset+1&&b[offset+1]==0x10){need(b[0]==0xC2,"Invalid inventory list envelope");auto items=decode_item_list(b,sizeof(PMSG_ITEM_LIST_SEND),INVENTORY_SIZE);auto boots=items.find(INVENTORY_SLOT_BOOTS);need(boots==items.end()||boots->second.index/512==11,"Non-boot item in equipped boot slot");state.items=std::move(items);state.ready=true;state.revision++;return true;}
 if(b[offset]==0xF3&&b.size()>offset+1&&b[offset+1]==0x14){need(b.size()==sizeof(PMSG_ITEM_MODIFY_SEND),"Invalid item modify reply");unsigned slot=b[offset+2];need(slot<INVENTORY_SIZE,"Invalid modified item slot");auto item=read(b,offset+3);need(slot!=INVENTORY_SLOT_BOOTS||item.index/512==11,"Non-boot item in equipped boot slot");state.items[slot]=std::move(item);state.revision++;return true;}
 if(b[offset]==0x22){need(b.size()==sizeof(PMSG_ITEM_GET_SEND),"Invalid pickup reply");unsigned slot=b[offset+1];if(slot>=0xFD)return true;need(slot>=12&&slot<INVENTORY_SIZE,"Invalid pickup slot");auto item=read(b,offset+2);need(!state.items.count(slot),"Pickup destination occupied");state.items[slot]=item;state.revision++;return true;}
 if(b[offset]==0x32){need(b.size()==sizeof(PMSG_ITEM_BUY_SEND),"Invalid buy reply");unsigned slot=b[offset+1];if(slot==255)return true;need(slot>=12&&slot<INVENTORY_SIZE,"Invalid purchased item slot");auto item=read(b,offset+2);need(!state.items.count(slot),"Purchased item destination already occupied");state.items[slot]=item;state.revision++;return true;}
 if(b[offset]==0x28){need(b.size()==sizeof(PMSG_ITEM_DELETE_SEND),"Invalid item delete reply");unsigned slot=b[offset+1];if(slot==255)return true;need(slot<INVENTORY_SIZE,"Invalid deleted item slot");if(state.items.erase(slot))state.revision++;return true;}
 if(b[offset]==0x23){need(b.size()==sizeof(PMSG_ITEM_DROP_SEND),"Invalid item drop reply");if(b[offset+1]!=1)return true;unsigned slot=b[offset+2];need(slot<INVENTORY_SIZE,"Invalid dropped item slot");if(state.items.erase(slot))state.revision++;return true;}
 if(b[offset]==0x2A){need(b.size()==sizeof(PMSG_ITEM_DUR_SEND),"Invalid durability reply");unsigned slot=b[offset+1];need(slot<INVENTORY_SIZE,"Invalid durability slot");auto found=state.items.find(slot);if(found!=state.items.end()&&found->second.durability!=b[offset+2]){found->second.durability=b[offset+2];found->second.wire[2]=b[offset+2];state.revision++;}return true;}
 return false;
}
}
namespace mu::client {
namespace {void checkMoveSlot(unsigned container,unsigned slot){need((container==0&&slot<76)||(container==2&&slot<120),"Only equipment, main bag and main warehouse are supported");}}
std::vector<std::uint8_t> item_move_packet(const ItemMove& move,const Item& item){checkMoveSlot(move.sourceContainer,move.sourceSlot);checkMoveSlot(move.targetContainer,move.targetSlot);need(move.sourceContainer!=move.targetContainer||move.sourceSlot!=move.targetSlot,"Item already occupies destination");PMSG_ITEM_MOVE_RECV packet{};packet.header.setE(0x24,sizeof(packet));packet.SourceFlag=move.sourceContainer;packet.SourceSlot=move.sourceSlot;packet.TargetFlag=move.targetContainer;packet.TargetSlot=move.targetSlot;std::copy(item.wire.begin(),item.wire.end(),packet.ItemInfo);auto first=reinterpret_cast<const std::uint8_t*>(&packet);return {first,first+sizeof(packet)};}
bool commit_item_move(InventorySnapshot& inventory,ItemSlots& warehouse,const ItemMove& move,const Item& original,const std::vector<std::uint8_t>& reply){checkMoveSlot(move.sourceContainer,move.sourceSlot);checkMoveSlot(move.targetContainer,move.targetSlot);need(reply.size()==sizeof(PMSG_ITEM_MOVE_SEND)&&reply[2]==0x24,"Malformed item move reply");need(reply[4]==move.targetSlot,"Item move destination mismatch");if(reply[3]==255)return false;need(reply[3]==move.targetContainer,"Item move container mismatch");auto confirmed=read(reply,5);need(confirmed.index==original.index,"Server move reply changed item type");auto nextInventory=inventory.items,nextWarehouse=warehouse;auto& source=move.sourceContainer==0?nextInventory:nextWarehouse;auto& target=move.targetContainer==0?nextInventory:nextWarehouse;auto found=source.find(move.sourceSlot);need(found!=source.end()&&found->second.wire==original.wire,"Move source changed while request pending");source.erase(found);need(!target.count(move.targetSlot),"Move target already occupied");target.emplace(move.targetSlot,confirmed);inventory.items=std::move(nextInventory);warehouse=std::move(nextWarehouse);if(move.sourceContainer==0||move.targetContainer==0)inventory.revision++;return true;}
}
